const Typesense = require('typesense');
const fs = require('fs');

let apiKey = 'xyz';
if (fs.existsSync('/etc/typesense-api-key')) {
  apiKey = fs.readFileSync('/etc/typesense-api-key', 'utf8').trim();
}

const client = new Typesense.Client({
  nodes: [{ host: '127.0.0.1', port: 8108, protocol: 'http' }],
  apiKey: apiKey,
  connectionTimeoutSeconds: 5
});

async function run() {
  try {
    // 1. Index products from catalog-seed.json
    const seedData = JSON.parse(fs.readFileSync('/home/user/trendsearch/catalog-seed.json', 'utf8'));
    console.log(`Loaded ${seedData.length} products from seed file.`);

    await client.collections('catalog').documents().import(seedData, { action: 'upsert' });
    console.log('Imported products into catalog.');

    // 2. Perform some search queries
    // We will run 'Laptop' multiple times
    console.log('Searching for "Laptop" 3 times...');
    for (let i = 0; i < 3; i++) {
      const res = await client.collections('catalog').documents().search({
        q: 'Laptop',
        query_by: 'name'
      });
      console.log(`Search Laptop ${i+1}: found ${res.found} hits.`);
    }

    // We will run 'Phone' 2 times
    console.log('Searching for "Phone" 2 times...');
    for (let i = 0; i < 2; i++) {
      const res = await client.collections('catalog').documents().search({
        q: 'Phone',
        query_by: 'name'
      });
      console.log(`Search Phone ${i+1}: found ${res.found} hits.`);
    }

    // We will run 'NonexistentQuery' 4 times
    console.log('Searching for "NonexistentQuery" 4 times...');
    for (let i = 0; i < 4; i++) {
      const res = await client.collections('catalog').documents().search({
        q: 'NonexistentQuery',
        query_by: 'name'
      });
      console.log(`Search NonexistentQuery ${i+1}: found ${res.found} hits.`);
    }

    // 3. Wait and poll the analytics collections
    console.log('Waiting for aggregation to flush...');
    for (let sec = 1; sec <= 5; sec++) {
      await new Promise(resolve => setTimeout(resolve, 1000));
      console.log(`Waited ${sec} seconds...`);

      const popularQueries = await client.collections('product_queries').documents().search({
        q: '*',
        query_by: 'q'
      });
      const nohitsQueries = await client.collections('nohits_queries').documents().search({
        q: '*',
        query_by: 'q'
