      console.log(`Popular queries in DB:`, popularQueries.hits.map(h => h.document));
      console.log(`No-hits queries in DB:`, nohitsQueries.hits.map(h => h.document));

      if (popularQueries.hits.length > 0 && nohitsQueries.hits.length > 0) {
        console.log('Aggregation successfully verified!');
        break;
      }
    }

  } catch (err) {
    console.error('Error:', err);
  }
}

